 x=np.asarray(a[y:y+32]);z=np.asarray(b[y:y+32]);d=z-x;stats['channels']+=d.size;stats['meanAbsLinearDelta']+=float(np.abs(d).sum());stats['maxAbsLinearDelta']=max(stats['maxAbsLinearDelta'],float(np.abs(d).max()));mask=(np.max(np.abs(x),axis=2)<.02);vals=d[mask];stats['darkCount']+=vals.size;stats['darkAbsDeltaSum']+=float(np.abs(vals).sum());stats['darkDeltaSqSum']+=float((vals.astype(float)**2).sum());grad=np.diff(z,axis=1)-np.diff(x,axis=1);stats['maxLocalGradientDelta']=max(stats['maxLocalGradientDelta'],float(np.abs(grad).max()))
